import { BaseHandler } from "./base.js";
import { ResponseBuilder } from "../../../security/index.js";
import { getConfig } from "../../../config/index.js";
import { PRIORITY_VERY_HIGH } from "../../../utils/constants/index.js";
import { resolveAppRouteFile } from "../request/api/app-router-resolver.js";
import { isSharedProjectRuntime, requiresIsolatedProjectRuntime, } from "../../../security/project-locality.js";
import { getApplicationPreflightHeaders } from "../../../security/http/application-request.js";
import { ensurePreviewSourceSnapshotFresh } from "../request/source-snapshot-freshness.js";
export class CorsHandler extends BaseHandler {
    metadata = {
        name: "CorsHandler",
        priority: PRIORITY_VERY_HIGH,
        patterns: [{ pattern: /.*/, method: "OPTIONS" }],
    };
    static DEFAULT_METHODS = "GET,POST,PUT,PATCH,DELETE,OPTIONS";
    resolveAppRouteFile;
    constructor(dependencies = {}) {
        super();
        this.resolveAppRouteFile = dependencies.resolveAppRouteFile ?? resolveAppRouteFile;
    }
    async handle(req, ctx) {
        if (req.method.toUpperCase() !== "OPTIONS")
            return this.continue();
        const pathname = new URL(req.url).pathname;
        const isSharedRuntime = isSharedProjectRuntime(ctx);
        const mustAvoidProjectCode = requiresIsolatedProjectRuntime(ctx);
        const isApiPath = pathname === "/api" || pathname.startsWith("/api/");
        const fsWrapper = ctx.adapter.fs;
        const hasContextualFilesystem = fsWrapper.isContextualMode?.() === true;
        const hasAtomicSharedRuntimeContext = isSharedRuntime &&
            !!ctx.projectSlug &&
            fsWrapper.isMultiProjectMode?.() === true &&
            typeof fsWrapper.runWithContext === "function";
        const shouldUseAutomaticPreflight = mustAvoidProjectCode ||
            (hasContextualFilesystem && !hasAtomicSharedRuntimeContext);
        if (!shouldUseAutomaticPreflight && isApiPath) {
            return this.continue();
        }
        if (!shouldUseAutomaticPreflight && !isApiPath) {
            const resolveMatchedRoute = async () => {
                await ensurePreviewSourceSnapshotFresh(ctx);
                return this.hasMatchedAppRoute(pathname, ctx);
            };
            const hasMatchedAppRoute = hasAtomicSharedRuntimeContext
                ? await fsWrapper.runWithContext(ctx.projectSlug, ctx.proxyToken ?? "", resolveMatchedRoute, ctx.projectId, {
                    productionMode: ctx.requestContext?.mode === "production",
                    releaseId: ctx.releaseId,
                    branch: ctx.requestContext?.mode === "production"
                        ? null
                        : ctx.requestContext?.branch ?? ctx.parsedDomain?.branch ?? null,
                    environmentName: ctx.environmentName,
                })
                : await resolveMatchedRoute();
            if (hasMatchedAppRoute)
                return this.continue();
        }
        let corsConfig = ctx.securityConfig?.cors;
        if (!isSharedRuntime) {
            try {
                const cfg = await getConfig(ctx.projectDir, ctx.adapter);
                corsConfig = cfg?.security?.cors ?? corsConfig;
            }
            catch (error) {
                // Falling back to ctx.securityConfig?.cors (set at request time). If that is
                // also absent, ResponseBuilder.preflight will use its own restrictive defaults.
                // Verify the fallback is not more permissive than the config-file value intended.
                this.logWarn("Failed to load CORS config — falling back to security-context defaults", { error });
            }
        }
        const response = ResponseBuilder.preflight(req, {
            allowMethods: CorsHandler.DEFAULT_METHODS,
            allowHeaders: getApplicationPreflightHeaders(req, {
                denyHeaders: ctx.applicationIdentityHeaderNames,
            }),
            securityConfig: ctx.securityConfig ?? undefined,
            corsConfig,
        });
        return this.respond(response);
    }
    async hasMatchedAppRoute(pathname, ctx) {
        try {
            const match = await this.resolveAppRouteFile(pathname, ctx);
            return match !== null;
        }
        catch (error) {
            this.logWarn("Failed to resolve route for CORS", { error, pathname });
            return false;
        }
    }
}
